{
  "card": "{{define "app-card-atom-begin-card"}}<article class="app-tile" data-app-tile="{{.Slug}}">{{end}}
{{define "app-card-atom-begin-summary"}}<a class="app-summary" href="{{.URL}}" data-app-open="{{.Slug}}">{{end}}
{{define "app-card-atom-icon"}}{{.Icon}}{{end}}
{{define "app-card-atom-begin-copy"}}<span class="app-copy">{{end}}
{{define "app-card-atom-name"}}<strong>{{.Name}}</strong>{{end}}
{{define "app-card-atom-description"}}<span>{{.Description}}</span>{{end}}
{{define "app-card-atom-end-copy"}}</span>{{end}}
{{define "app-card-atom-end-summary"}}</a>{{end}}
{{define "app-card-atom-manage"}}<a class="control-icon-button" href="{{.URL}}" data-app-open="{{.Slug}}" data-app-manage {{if .ManageHidden}}hidden{{end}} aria-label="{{.ManageLabel}}: {{.Name}}" title="{{.ManageLabel}}">{{.More}}</a>{{end}}
{{define "app-card-atom-connect"}}{{if .Unavailable}}<a class="control-icon-button" href="{{.URL}}" data-app-open="{{.Slug}}" data-app-add {{if .AddHidden}}hidden{{end}} aria-label="{{.AboutLabel}}: {{.Name}}">{{.Plus}}</a>{{else}}<form method="post" action="/apps/configure" data-app-action data-app-toolkit="{{.Slug}}" data-app-quick {{if .AddHidden}}hidden{{end}}>{{.InterfaceReference}}<input type="hidden" name="action" value="connect"><input type="hidden" name="toolkit" value="{{.Slug}}"><button class="control-icon-button" type="submit" aria-label="{{.ConnectLabel}} {{.Name}}" title="{{.ConnectLabel}}">{{.Plus}}</button></form>{{end}}{{end}}
{{define "app-card-atom-end-card"}}</article>{{end}}
",
  "sidebar": "{{define "app-sidebar-atom-begin-entry"}}<a href="{{.URL}}" data-app-open="{{.Slug}}">{{end}}
{{define "app-sidebar-atom-icon"}}{{.Icon}}{{end}}
{{define "app-sidebar-atom-name"}}<span>{{.Name}}</span>{{end}}
{{define "app-sidebar-atom-pending"}}{{if .Pending}}<span class="app-pending-dot" aria-label="{{.PendingLabel}}"></span>{{end}}{{end}}
{{define "app-sidebar-atom-end-entry"}}</a>{{end}}
",
  "graphics": "{{define "app-icon"}}<span class="app-logo" aria-hidden="true"><span>{{.Initial}}</span>{{if .HasIcon}}<img src="{{.IconURL}}" alt="" width="36" height="36" loading="lazy" decoding="async">{{end}}</span>{{end}}
{{define "app-plus"}}<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M12 4v16M4 12h16"/></svg>{{end}}
{{define "app-more"}}<svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="5" cy="12" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="19" cy="12" r="1.5"/></svg>{{end}}
",
  "account": "{{define "app-account-view-copy"}}<div class="setting-copy"><strong>{{.Name}} · {{.Alias}}</strong><p data-connection-status="{{.Status}}">{{.StatusLabel}}</p>{{.Warning}}
{{.Authorization}}</div>
{{end}}
{{define "app-account-view-actions"}}<form method="post" action="/apps/configure" data-app-action class="app-account-actions" data-settings-confirm="{{.Confirm}}" data-confirm-description="{{.Description}}">{{.Identity}}{{.Buttons}}</form>{{end}}
{{define "app-account-view-button"}}<button class="secondary" name="action" value="{{.Action}}">{{.Label}}</button>{{end}}
",
  "connect": {
    "program": "{{define "app-connect-view-unavailable"}}<span class="app-unavailable-action"><button type="button" disabled>{{.ConnectLabel}}</button>{{.Help}}</span>
{{end}}
{{define "app-connect-view-first"}}<form method="post" action="/apps/configure" data-app-action data-app-toolkit="{{.Slug}}" data-app-first {{if .FirstHidden}}hidden{{end}}>{{.Identity}}<button type="submit">{{.FirstLabel}}</button></form>
{{end}}
{{define "app-connect-view-additional"}}<details class="app-add-account" data-app-add-account {{if .AdditionalHidden}}hidden{{end}}><summary>{{.AddAccountLabel}}</summary><form method="post" action="/apps/configure" data-app-action data-app-toolkit="{{.Slug}}" data-app-additional>{{.Identity}}<label>{{.AccountLabel}}<input name="alias" placeholder="work" pattern="[A-Za-z0-9][A-Za-z0-9_-]{0,63}" maxlength="64" required></label><button type="submit">{{.ConnectAccountLabel}}</button></form></details>{{end}}
",
    "en": {
      "connect_label": "Connect",
      "account_label": "Account label",
      "connect_account_label": "Connect account"
    },
    "zh-CN": {
      "connect_label": "连接",
      "account_label": "账户别名",
      "connect_account_label": "连接账户"
    }
  },
  "settings": {
    "program": "{{define "app-settings-view-project"}} <section class="service-configuration"><h2 class="settings-section-title" aria-label="{{.ProjectTitle}}">{{.ProjectTitle}}{{.ProjectHelp}}</h2>

 <form method="post" action="/apps/service/configure">{{.Identity}}<div class="setting-row"><label for="composio-key-ref"><span class="control-field-label">{{.KeyRefLabel}}{{.KeyHelp}}</span></label><div class="setting-controls"><input id="composio-key-ref" name="key_ref" value="{{.KeyRef}}" placeholder="env:COMPOSIO_API_KEY" required autocomplete="off" aria-label="{{.KeyRefLabel}}"></div></div><input type="hidden" name="editor" value="fields"><details class="service-advanced" {{if .AdvancedOpen}}open{{end}}><summary>{{.AuthenticationTitle}}</summary>
 {{.Rows}}
 <div class="settings-actions"><button class="secondary setting-action" name="action" value="add-override" formnovalidate>{{.AddLabel}}</button></div></details><div class="settings-actions"><button type="submit" class="secondary setting-action">{{.SaveLabel}}</button></div></form>
 </section>
{{end}}
{{define "app-settings-view-row"}}<fieldset><legend class="sr-only">{{.AuthenticationTitle}}</legend><label>{{.AppLabel}}<input name="app_slug" value="{{.App}}" maxlength="128" spellcheck="false" autocomplete="off" placeholder="gmail"></label><label>{{.ConfigLabel}}<input name="auth_config" value="{{.Config}}" maxlength="128" spellcheck="false" autocomplete="off"></label><div class="settings-actions"><button class="secondary setting-action" name="action" value="remove-override-{{.Index}}" formnovalidate>{{.RemoveLabel}}</button></div></fieldset>{{end}}
",
    "en": {
      "key_ref_label": "API key reference",
      "app_label": "App identifier",
      "config_label": "Configuration ID",
      "remove_label": "Remove override",
      "add_label": "Add override",
      "save_label": "Verify and save"
    },
    "zh-CN": {
      "key_ref_label": "API key 引用",
      "app_label": "应用标识",
      "config_label": "授权配置 ID",
      "remove_label": "移除自定义配置",
      "add_label": "添加自定义配置",
      "save_label": "验证并保存"
    }
  },
  "directory": "{{define "app-directory-view-tabs"}} <nav class="apps-tabs" aria-label="{{.AppViews}}"><a href="/settings/apps" {{if .DiscoverCurrent}}aria-current="page"{{end}}>{{.Discover}}</a><a href="/settings/apps?view=connected" {{if .ConnectedCurrent}}aria-current="page"{{end}}>{{.YourApps}}</a><a href="/settings/apps?view=all" {{if .DirectoryCurrent}}aria-current="page"{{end}}>{{.AllApps}}</a></nav>
{{end}}
{{define "app-directory-view-collection-back"}} {{if .CollectionPresent}}<a class="back-link" href="/settings/apps">{{.BackToApps}}</a>{{end}}
{{end}}
{{define "app-directory-view-categories"}} {{if .CategoriesPresent}}<form method="get" action="/settings/apps" class="apps-filter" data-app-category-form><input type="hidden" name="view" value="all"><input type="hidden" name="search" value="{{.Search}}"><label for="app-category" class="sr-only">{{.CategoryLabel}}</label><select id="app-category" name="category"><option value="">{{.AllCategories}}</option>{{.Options}}</select><noscript><button class="secondary">{{.Filter}}</button></noscript></form>{{end}}
{{end}}
{{define "app-directory-view-pagination"}} {{if .PaginationPresent}}<a class="button secondary" href="/settings/apps?view=all&amp;search={{.Search}}&amp;category={{.Category}}&amp;cursor={{.NextCursor}}">{{.MoreApps}}</a>{{end}}
{{end}}
{{define "app-directory-view-option"}}<option value="{{.OptionID}}" {{if .OptionSelected}}selected{{end}}>{{.OptionName}}</option>{{end}}
",
  "pages": "{{define "app-page-view-page-heading"}} <div class="page-heading apps-heading"><div><h1>{{.AppsTitle}}</h1></div>
 <div class="apps-toolbar"><a class="control-icon-button" href="/settings/apps/service" aria-label="{{.AppSettings}}" title="{{.AppSettings}}">{{.SettingsIcon}}</a>{{if .SearchVisible}}<form method="get" action="/settings/apps" class="apps-search control-search" role="search"><input type="hidden" name="view" value="all"><input type="hidden" name="category" value="{{.Category}}"><label for="app-search" class="sr-only">{{.SearchApps}}</label><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input type="search" id="app-search" name="search" value="{{.SearchValue}}" maxlength="200" placeholder="{{.SearchApps}}"><button class="sr-only" type="submit">{{.Search}}</button></form>{{end}}<a class="control-icon-button" href="/settings/apps" aria-label="{{.RefreshApps}}" title="{{.RefreshApps}}"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 12-1l2 3M4 15l2 3a7 7 0 0 0 12-1"/></svg></a></div></div>
{{end}}
{{define "app-page-view-page-unavailable"}} {{if .Unavailable}}<p class="apps-notice" role="alert">{{.DirectoryUnavailable}}</p>{{end}}
{{end}}
{{define "app-page-view-page-feedback"}} <p class="feedback" role="status" aria-live="polite" data-app-feedback hidden></p>
{{end}}
{{define "app-page-view-page-inventory"}} <div id="app-accounts" hidden>{{.Inventory}}</div>
{{end}}
{{define "app-page-view-page-body"}} {{if .Selected}}<a class="back-link" href="/settings/apps">{{.BackToApps}}</a><section class="app-detail-page">{{.Detail}}</section>{{else}}
{{.Directory}} {{end}}
{{end}}
{{define "app-page-view-page-dialog"}} <dialog class="control-dialog apps-dialog" data-app-dialog aria-labelledby="app-dialog-title"><button type="button" class="control-icon-button apps-dialog-close" data-app-close aria-label="{{.Close}}"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="m6 6 12 12M6 18 18 6"/></svg></button><div data-app-dialog-body></div></dialog>
{{end}}
{{define "app-page-view-detail-heading"}}{{if .Selected}}<header>{{.Icon}}<div><h2>{{.Name}}</h2><p>{{.Description}}</p></div></header>
{{end}}{{end}}
{{define "app-page-view-detail-feedback"}}{{if .Selected}}<p class="feedback" data-app-detail-feedback role="status" aria-live="polite" hidden></p>
{{end}}{{end}}
{{define "app-page-view-detail-accounts"}}{{if .Selected}}<h3>{{.YourConnections}}</h3><div data-app-detail-accounts>{{.Accounts}}</div><p class="muted" data-app-no-accounts {{if .EmptyHidden}}hidden{{end}}>{{.NoConnections}}</p>
{{end}}{{end}}
{{define "app-page-view-service-heading"}} <div class="page-heading"><div><h1>{{.ServiceTitle}}</h1></div></div>
{{end}}
{{define "app-page-view-service-back"}} <a class="back-link" href="/settings/apps">{{.BackToApps}}</a>
{{end}}
{{define "app-page-view-page"}}
<section class="workspace-page settings-page apps-page" data-apps data-app-revision="{{.Revision}}" data-app-interface-mode="{{.InterfaceMode}}" data-app-interface-revision="{{.InterfaceRevision}}" data-app-interface-profile="{{.InterfaceProfile}}"{{if .Localized}} data-app-interface-localized="true"{{end}}>
{{.Body}}</section>
{{end}}

{{define "app-page-view-service"}}
<section class="workspace-page settings-page">
{{.Body}}</section>
{{end}}

{{define "app-page-view-sidebar"}}
{{if .ManagedPresent}}<p class="settings-nav-heading apps-sidebar-heading">{{.ConnectedApps}}</p><nav class="section-navigation apps-connections" aria-label="{{.ConnectedApps}}">{{.Entries}}</nav>{{end}}
{{end}}
{{define "app-page-view-detail"}}
{{if .Selected}}<div class="app-detail" data-app-detail="{{.Slug}}"{{if .HasInterface}} data-app-no-auth="{{.NoAuth}}" data-app-suggested="{{.Suggested}}"{{end}}>{{.Body}}</div>{{end}}
{{end}}

{{define "app-page-view-account-row"}}<div class="app-account" data-app-account="{{.ID}}" data-app-slug="{{.Toolkit}}" data-app-state="{{.Status}}" data-app-public="{{.Public}}">{{.Body}}</div>{{end}}
{{define "app-page-view-accounts"}}
{{.Accounts}}
{{end}}

{{define "app-page-view-group"}}<section class="apps-group"><div class="apps-group-heading"><h2>{{.Title}}</h2>{{if .HasURL}}<a class="text-link" href="{{.URL}}" aria-label="{{.ViewAll}}: {{.Title}}">{{.ViewAll}}<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></a>{{end}}</div><div class="apps-grid">{{.Cards}}</div></section>{{end}}
{{define "app-page-view-groups"}} {{if .GroupsPresent}}{{.Groups}}{{else}}<p class="apps-empty">{{.NoApps}}</p>{{end}}
{{end}}
"
}
